import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Guía de desarrollo","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/dev-guide/index.md","filePath":"es-ES/dev-guide/index.md","lastUpdated":1787586465000}'),d={name:"es-ES/dev-guide/index.md"};function i(s,e,c,l,n,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="guia-de-desarrollo" tabindex="-1">Guía de desarrollo <a class="header-anchor" href="#guia-de-desarrollo" aria-label="Permalink to &quot;Guía de desarrollo&quot;">​</a></h1><p>Bienvenido al Manual de referencia para desarrolladores de Lertaro. Diseñado sobre una arquitectura desacoplada y un ecosistema de plugins extensible, Lertaro proporciona un SDK oficial: <code>Lertaro.PluginSdk</code>. Al utilizar este SDK, los desarrolladores pueden aportar fuentes de búsqueda personalizadas, ampliar menús de acciones contextuales, integrarse con exploradores de archivos y cuadros de diálogo nativos, y crear temas o visores de vista previa a medida.</p><h2 id="_1-arquitectura-y-flujo-de-trabajo" tabindex="-1">1. Arquitectura y flujo de trabajo <a class="header-anchor" href="#_1-arquitectura-y-flujo-de-trabajo" aria-label="Permalink to &quot;1. Arquitectura y flujo de trabajo&quot;">​</a></h2><ul><li><strong><a href="./architecture.html">Arquitectura del sistema</a></strong> —— Explicación del modelo de aislamiento de tres procesos (Servicio de Windows a nivel SYSTEM, App WPF en modo usuario y proceso de interceptación de teclado Hook) y la comunicación IPC por tuberías con nombre.</li><li><strong><a href="./getting-started.html">Guía de inicio rápido</a></strong> —— Guía paso a paso para crear un proyecto de librería, referenciar el SDK, implementar <code>IPlugin</code> y depurar localmente.</li><li><strong><a href="./packaging.html">Empaquetado y distribución</a></strong> —— Estructura de carpetas de plugins, inclusión de librerías dependientes administradas y nativas, recursos i18n incrustados y automatización PostBuild.</li><li><strong><a href="./examples.html">Ejemplos de plugins</a></strong> —— Análisis en profundidad del código de los plugins oficiales de código abierto <code>CoreExtensions</code>, <code>PinyinAlias</code> y <code>FlowLauncherBridge</code>.</li></ul><h2 id="_2-referencia-de-la-api-del-sdk" tabindex="-1">2. Referencia de la API del SDK <a class="header-anchor" href="#_2-referencia-de-la-api-del-sdk" aria-label="Permalink to &quot;2. Referencia de la API del SDK&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Categoría del SDK</th><th style="text-align:left;">Interfaces y servicios principales</th><th style="text-align:left;">Descripción de capacidades</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./sdk/core-search-actions.html">Búsqueda central y acciones</a></strong></td><td style="text-align:left;"><code>ISearchableItemProvider</code><br><code>IInstantResultProvider</code><br><code>IAliasProvider</code><br><code>IQueryTokenProvider</code><br><code>ISearchResultAction</code><br><code>IDynamicActionProvider</code></td><td style="text-align:left;">Aportar elementos indexados, respuestas de cálculo instantáneo, motores de transliteración de alias no ASCII, manejadores de tokens de sufijo y menús de acciones estáticos o dinámicos.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/system-adapters.html">Adaptadores de sistema y diálogo</a></strong></td><td style="text-align:left;"><code>IActivePathCollector</code><br><code>IFileDialogAdapter</code><br><code>IInlineSearchAdapter</code><br><code>IQuickNavigationProvider</code></td><td style="text-align:left;">Detectar directorios activos en exploradores, enganchar diálogos nativos de archivos, incrustar la barra de búsqueda con sincronización bidireccional y menús de Navegación rápida.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/ui-extensions.html">Extensiones de interfaz y vista previa</a></strong></td><td style="text-align:left;"><code>ISidebarFilterProvider</code><br><code>IResultColumnProvider</code><br><code>IQuickPanelTabProvider</code><br><code>IFilePreviewProvider</code><br><code>IThumbnailProvider</code><br><code>IThemeProvider</code><br><code>ITranslationProvider</code></td><td style="text-align:left;">Categorías de filtro lateral, columnas personalizadas en tablas, pestañas dinámicas en el Panel rápido, renderizadores de vista previa en QuickLook, extracción de miniaturas, temas WPF e idiomas i18n.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/abstractions.html">Abstracciones compartidas</a></strong></td><td style="text-align:left;"><code>ISearchResult</code><br><code>FileMetadata</code><br><code>IPluginSearchWindow</code><br><code>IConfigurable</code></td><td style="text-align:left;">Modelos de resultados de solo lectura, metadatos de archivos de alta precisión, controladores seguros de la ventana anfitriona y formularios de configuración basados en esquemas.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/services.html">Servicios del anfitrión</a></strong></td><td style="text-align:left;"><code>FuzzyMatchService</code><br><code>TranslationService</code><br><code>IconService</code><br><code>FavoritesService</code><br><code>HistoryService</code><br><code>FileMetadataService</code><br><code>DirectoryIndexerService</code><br><code>RecentFilesService</code><br><code>ExplorerPathService</code><br><code>PluginSettingsService</code><br><code>SearchRefreshService</code><br><code>UserDataService</code><br><code>Logger</code></td><td style="text-align:left;">Infraestructura de alto rendimiento: coincidencia difusa fzf y máscaras de resaltado, extracción de iconos con caché, consulta de favoritos/historial, proxies de indexación, aislamiento de datos y operaciones Shell.</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Todas las firmas de métodos, parámetros y contratos de comportamiento de este manual han sido contrastados directamente con el código fuente de <code>Lertaro.PluginSdk</code>.</p></div>',7)])])}const m=a(d,[["render",i]]);export{g as __pageData,m as default};
